def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def _validate(name, lessons, questions, want_ch):
    problems = []
    if len(lessons) != want_ch:
        problems.append(f"  {name}: {len(lessons)} lessons (want {want_ch})")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in lessons if len(l["html"]) < 2500]
    if short:
        problems.append(f"  {name} below depth: {short}")
    if len(questions) != 35:
        problems.append(f"  {name}: {len(questions)} questions (want 35)")
    for q in questions:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  {name} malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": lessons, "q": questions}):
        problems.append(f"  {name}: ERPNext branding leakage")
    return problems


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)

    if '"3.174.0"' in init:
        print("Already applied. Nothing to do.")
        return
    if '"3.173.0"' not in init:
        sys.exit("ABORT: not at v3.173.0.")
    for k in ("employee_master", "recruitment"):
        if k not in data:
            sys.exit(f"ABORT: {k} module not found in data file.")

    problems = _validate("HR1", LESSONS_H1, QUESTIONS_H1, 9) + _validate("HR2", LESSONS_H2, QUESTIONS_H2, 9)
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    for name, lessons, questions, key, desc in (
        ("HR 1", LESSONS_H1, QUESTIONS_H1, "employee_master",
         "The Employee master in ZhiftERP: the organisational masters (Branch, Department tree with approver tables, Designation, Employment Type, Employee Grade) in build order; the Employee record's identity, joining, organisational, contact, personal, and bank field groups with what reads each field; the joiner verification procedure; the status lifecycle with the two-field exit rule and recorded changes; the Reports To structure and the Organizational Chart page; and the monthly and quarterly register hygiene reads."),
        ("HR 2", LESSONS_H2, QUESTIONS_H2, "recruitment",
         "Recruitment in ZhiftERP: the six-stage pipeline from Staffing Plan (details table, plan validation, plan-versus-actual) through Job Opening (status discipline, openings read), Job Applicant (status pipeline, source tracking, funnel and aging reads, data handling), Interview (Interview Round skill sets, same-day Interview Feedback), and Job Offer (complete terms table, letter print, offer register) to Employee creation from the applicant and Employee Onboarding from a template with the pre-joining check."),
    ):
        bank = rebalance(list(questions))
        dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
        if max(dist.values()) > 10:
            print(f"ABORT — {name} spread failed: {dist}")
            sys.exit(1)
        total = sum(len(l["html"]) for l in lessons)
        print(f"{name} v3: {len(lessons)} chapters ({total:,} chars, min {min(len(l['html']) for l in lessons):,}), bank {len(bank)}, spread {dist}")
        if not CHECK_ONLY:
            data[key]["lessons"] = lessons
            data[key]["questions"] = bank
            data[key]["desc"] = desc

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.173.0"', '"3.174.0"'))
    print("  data: HR 1 + 2 lessons + banks REPLACED (style v3, strict manual register)")
    print("wrote __version__ -> 3.174.0")


if __name__ == "__main__":
    main()
